    1	// Package duration parses the human-friendly durations remind accepts,
    2	// such as "90s", "1h30m", "2d", and "1w2d".
    3	package duration
    4	
    5	import (
    6		"fmt"
    7		"strconv"
    8		"strings"
    9		"time"
   10	)
   11	
   12	// Day and Week are the units Parse adds to the standard library's.
   13	const (
   14		Day  = 24 * time.Hour
   15		Week = 7 * Day
   16	)
   17	
   18	var units = map[byte]time.Duration{
   19		's': time.Second,
   20		'm': time.Minute,
   21		'h': time.Hour,
   22		'd': Day,
   23		'w': Week,
   24	}
   25	
   26	// Parse parses a sequence of whole numbers, each followed by a unit:
   27	// s, m, h, d (24 hours), or w (7 days). "1h30m" is ninety minutes.
   28	func Parse(s string) (time.Duration, error) {
   29		if last := s[len(s)-1]; last >= '0' && last <= '9' {
   30			return 0, fmt.Errorf("duration %q: missing unit", s)
   31		}
   32		var total time.Duration
   33		for rest := s; rest != ""; {
   34			i := 0
   35			for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
   36				i++
   37			}
   38			if i == 0 {
   39				return 0, fmt.Errorf("duration %q: expected a number at %q", s, rest)
   40			}
   41			n, err := strconv.Atoi(rest[:i])
   42			if err != nil {
   43				return 0, fmt.Errorf("duration %q: %w", s, err)
   44			}
   45			unit, ok := units[rest[i]]
   46			if !ok {
   47				return 0, fmt.Errorf("duration %q: unknown unit %q", s, rest[i])
   48			}
   49			total += time.Duration(n) * unit
   50			rest = rest[i+1:]
   51		}
   52		return total, nil
   53	}
   54	
   55	// Format formats d the way Parse reads it, largest units first.
   56	// Parts smaller than a second are dropped.
   57	func Format(d time.Duration) string {
   58		if d < time.Second {
   59			return "0s"
   60		}
   61		var b strings.Builder
   62		for _, u := range []struct {
   63			size time.Duration
   64			name byte
   65		}{{Week, 'w'}, {Day, 'd'}, {time.Hour, 'h'}, {time.Minute, 'm'}, {time.Second, 's'}} {
   66			if n := d / u.size; n > 0 {
   67				b.WriteString(strconv.FormatInt(int64(n), 10))
   68				b.WriteByte(u.name)
   69				d -= n * u.size
   70			}
   71		}
   72		return b.String()
   73	}

