  210	// Upcoming returns the times a user's reminders fire in [from, to),
  211	// sorted by time. Recurring reminders appear once per occurrence.
  212	func (s *Store) Upcoming(userID string, from, to time.Time) []Occurrence {
  213		s.mu.RLock()
  214		defer s.mu.RUnlock()
  215		var out []Occurrence
  216		for _, r := range s.byUser[userID] {
  217			if r.Done || r.Deleted {
  218				continue
  219			}
  220			if r.Rule == nil {
  221				if !r.Due.Before(from) && r.Due.Before(to) {
  222					out = append(out, Occurrence{ReminderID: r.ID, Text: r.Text, At: r.Due})
  223				}
  224				continue
  225			}
  226			t := r.Rule.Next(from)
  227			for n := 0; !t.IsZero() && t.Before(to) && n < maxOccurrences; n++ {
  228				out = append(out, Occurrence{ReminderID: r.ID, Text: r.Text, At: t})
  229				t = r.Rule.Next(t)
  230			}
  231		}
  232		slices.SortStableFunc(out, func(a, b Occurrence) int { return cmp.Compare(a.At.UnixNano(), b.At.UnixNano()) })
  233		return out
  234	}
